import { mount, signal } from 'kerfjs';
import { delegateActions } from 'kerfjs/actions';
import { PageHeader } from '@kerfjs/ui/page-header';
import { EmptyState } from '@kerfjs/ui/empty-state';
import { StateBanner } from '@kerfjs/ui/state-banner';
import { LoadingSpinner } from '@kerfjs/ui/loading-spinner';
import '@kerfjs/ui/layout.css';
import './workspace.css';
type Row = { id: string; title: string; status: string };
export function mountWorkspace(root: HTMLElement, app: { load(signal: AbortSignal): Promise<Row[]>; create(): void }) {
 const rows = signal<Row[]>([]);
 const state = signal<'loading' | 'empty' | 'populated' | 'refreshing' | 'error'>('loading');
 const loaded = signal(false);
 let request: AbortController | undefined;
 let disposed = false;
 const fetchRows = async () => {
  request?.abort();
  const current = new AbortController(); request = current;
  state.value = loaded.value ? 'refreshing' : 'loading';
  try {
   const next = await app.load(current.signal);
   if (disposed || current !== request || current.signal.aborted) return;
   rows.value = next; loaded.value = true; state.value = next.length ? 'populated' : 'empty';
  } catch {
   if (!disposed && current === request && !current.signal.aborted) state.value = 'error';
  }
 };
 const stopMount = mount(root, () => <section class="workspace kui-layout">
  <PageHeader title="Tasks" action={<div class="kui-control-cluster"><button type="button" data-action="create">New task</button><button type="button" data-action="refresh" disabled={state.value === 'loading' || state.value === 'refreshing'}>Refresh</button></div>} />
  <div class="kui-pane-body kui-scroll-owner kui-section-stack">
   {state.value === 'loading' && <EmptyState title="Loading tasks" detail="Retrieving your workspace." busy />}
   {state.value === 'refreshing' && <StateBanner title="Refreshing tasks" detail="Saved results remain available." action={<LoadingSpinner label="Refresh in progress" />} />}
   {state.value === 'error' && <StateBanner title="Tasks could not be loaded" detail={loaded.value ? 'Your saved results are still shown. Retry to get the latest changes.' : 'Check your connection and retry.'} tone="danger" urgency="alert" action={<button type="button" data-action="refresh">Retry</button>} />}
   {loaded.value && rows.value.length === 0 && <EmptyState title="No tasks yet" detail="Create a task to get started." action={<button type="button" data-action="create">Create task</button>} />}
   {rows.value.length > 0 && <ul class="workspace-list" aria-label="Tasks">{rows.value.map(row => <li data-key={row.id}><strong>{row.title}</strong><span class="kui-inline-metadata">{row.status}</span></li>)}</ul>}
  </div>
 </section>);
 const stopActions = delegateActions(root, 'click', { refresh: () => { void fetchRows(); }, create: () => app.create() });
 void fetchRows();
 return () => { disposed = true; request?.abort(); stopActions(); stopMount(); };
}

