.workspace { height: 100%; min-height: 0; min-width: 0; display: grid; grid-template-rows: auto minmax(0,1fr); color: var(--kui-color-text); }
.workspace-list { margin: 0; padding: 0; list-style: none; }
.workspace-list li { display: grid; gap: var(--kui-layout-metadata-gap); padding-block: var(--kui-space-s); border-bottom: 1px solid var(--kui-color-border); overflow-wrap: anywhere; }
.workspace button { min-height: 2rem; font: inherit; color: var(--kui-color-text); background: var(--kui-color-surface); border: 1px solid var(--kui-color-border); border-radius: var(--kui-radius-m); }
.workspace button:focus-visible { outline: var(--kui-focus-ring); }
